/* eslint-disable import/first */
import React, { Component } from "react";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import Loader from "react-loader-spinner";
import "react-dates/lib/css/_datepicker.css";
import Pagination2 from "react-js-pagination";
import { FormattedMessage } from "react-intl";
require("jspdf-autotable");
import classnames from "classnames";

// Redux
import { connect } from "react-redux";
import { bindActionCreators } from "redux";
import {
	// action creatores
	fetchpostilionSummary,
	fetchPostilionSummaryItem,
	fetchFlexcubeSummary,
	fetchPOSacquirersSummary,
} from "../../../actions/filesets";

// components
import { Col, Row, Table, Nav, NavItem, NavLink, TabContent, TabPane } from "reactstrap";
// import PostingTable from '../../../components/PostingTable';
import PostingTableHeader from "../../../components/PostingTableHeader";
import SettlementTable from "../../../components/SettlementTable";

class Summary extends Component {
	constructor (props) {
		super(props);
		this.state = {
			activePage    : 1,
			activePageFx  : 1,
			activePagePOS : 1,
			activeTab     :
				props.match.params.logName === "postilion"
					? { id: "1", name: "postilion" }
					: props.match.params.logName === "flexcube"
						? { id: "2", name: "flexcube" }
						: { id: "3", name: "pos-acquirer" },
		};
	}

	static getDerivedStateFromProps (props, state) {
		if (props.match.params.page !== state.activePage) {
			return {
				activePage : parseInt(props.match.params.page),
			};
		}

		if (props.match.params.page !== state.activePageFx) {
			return {
				activePageFx : parseInt(props.match.params.page),
			};
		}

		if (props.match.params.page !== state.activePagePOS) {
			return {
				activePagePOS : parseInt(props.match.params.page),
			};
		}

		// Return null if the state hasn't changed
		return null;
	}

	componentDidMount () {
		this.props.fetchpostilionSummary(this.props.match.params.page - 1);
		this.props.fetchFlexcubeSummary(this.props.match.params.page - 1);
		this.props.fetchPOSacquirersSummary(this.props.match.params.page - 1);
	}

	componentDidUpdate (prevProps) {
		if (this.props.match.params.logName !== this.state.activeTab["name"]) {
			this.setState({
				activeTab :
					this.props.match.params.logName === "postilion"
						? { id: "1", name: "postilion" }
						: this.props.match.params.logName === "flexcube"
							? { id: "2", name: "flexcube" }
							: { id: "3", name: "pos-acquirer" },
			});
		}

		if (this.props.match.params.logName !== prevProps.match.params.logName) {
			if (this.props.match.params.logName === "postilion") {
				this.props.fetchpostilionSummary(this.props.match.params.page - 1);
			}

			if (this.props.match.params.logName === "flexcube") {
				this.props.fetchFlexcubeSummary(this.props.match.params.page - 1);
			}

			if (this.props.match.params.logName === "pos-acquirer") {
				this.props.fetchPOSacquirersSummary(this.props.match.params.page - 1);
			}
		}

		if (this.props.match.params.page !== prevProps.match.params.page) {
			if (this.props.match.params.logName === "postilion") {
				this.props.fetchpostilionSummary(this.props.match.params.page - 1);
			}

			if (this.props.match.params.logName === "flexcube") {
				this.props.fetchFlexcubeSummary(this.props.match.params.page - 1);
			}

			if (this.props.match.params.logName === "pos-acquirer") {
				this.props.fetchPOSacquirersSummary(this.props.match.params.page - 1);
			}
		}
	}

	handlePageChange = (pageNumber) => {
		this.props.history.push(`/downstream/logs/postilion/${pageNumber}`);
		this.setState({ activePage: pageNumber });
	};

	handlePageChangeFx = (pageNumber) => {
		this.props.history.push(`/downstream/logs/flexcube/${pageNumber}`);
		this.setState({ activePageFx: pageNumber });
	};

	handlePageChangePOS = (pageNumber) => {
		this.props.history.push(`/downstream/logs/pos-acquirer/${pageNumber}`);
		this.setState({ activePagePOS: pageNumber });
	};

	toggle (tab) {
		this.props.history.push(`/downstream/logs/${tab.name}/1`);
		if (this.props.match.params.logName === "postilion") {
			this.setState({
				activeTab  : { id: "1", name: "postilion" },
				activePage : 1,
			});
		}

		if (this.props.match.params.logName === "flexcube") {
			this.setState({
				activeTab    : { id: "2", name: "flexcube" },
				activePageFx : 1,
			});
		}

		if (this.props.match.params.logName === "pos-acquirer") {
			this.setState({
				activeTab     : { id: "3", name: "pos-acquirer" },
				activePagePOS : 1,
			});
		}
	}

	render () {
		// setting the table header array to use with the reuable PostingTableHeader component
		const headerPayload = [ "Date", "File Name", "Action" ];

		if (!this.props.postilionLogSummary) {
			// Throw loader if summary log data is not available
			return (
				<Row>
					<Col xs={10} className={"mx-auto"}>
						<Loader
							type='ThreeDots'
							color='#00BFFF'
							height={100}
							width={100}
							style={{ textAlign: "center" }}
						/>
					</Col>
				</Row>
			);
		}

		return (
			<div className='animated fadeIn'>
				<Row>
					<Col xs='12' md='12' className='mb-4'>
						<Nav tabs>
							<NavItem>
								<NavLink
									className={classnames({ active: this.state.activeTab["id"] === "1" })}
									onClick={() => {
										this.toggle({ id: "1", name: "postilion" });
									}}
								>
									<i className='fa fa-table mx-1' aria-hidden='true' style={{ color: "#269AB7" }} />
									<FormattedMessage id='Postilion' defaultMessage='Postilion' />
								</NavLink>
							</NavItem>

							<NavItem>
								<NavLink
									className={classnames({ active: this.state.activeTab["id"] === "2" })}
									onClick={() => {
										this.toggle({ id: "2", name: "flexcube" });
									}}
								>
									<i className='fa fa-table mx-1' aria-hidden='true' style={{ color: "#269AB7" }} />
									<FormattedMessage id='Flexcube' defaultMessage='Flexcube' />
								</NavLink>
							</NavItem>

							<NavItem>
								<NavLink
									className={classnames({ active: this.state.activeTab["id"] === "3" })}
									onClick={() => {
										this.toggle({ id: "3", name: "pos-acquirer" });
									}}
								>
									<i className='fa fa-table mx-1' aria-hidden='true' style={{ color: "#269AB7" }} />
									<FormattedMessage id='POS Acquirers' defaultMessage='POS Acquirers' />
								</NavLink>
							</NavItem>
						</Nav>

						<TabContent activeTab={this.state.activeTab["id"]}>
							<TabPane tabId='1'>
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
									id='divToPDF'
								>
									<thead className='thead-light'>
										<PostingTableHeader headerType={"array"} headerPayload={headerPayload} />
									</thead>
									<tbody>
										<SettlementTable
											summaryType={"postilion"}
											Error404Msg={"There is no Postilion entry for this date!"}
											title={"View Postilion Summary"}
											url={"/downstream/logs/"}
											getItemFunc={() => this.fetchPostilionSummaryItem}
											summaryPayload={
												this.props.postilionLogSummary ? (
													this.props.postilionLogSummary.content
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table>

								{this.props.postilionLogSummary ? (
									<nav>
										<Pagination2
											activePage={this.state.activePage}
											itemsCountPerPage={this.props.postilionLogSummary.size}
											totalItemsCount={
												(this.props.postilionLogSummary &&
													this.props.postilionLogSummary.totalElements) ||
												null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChange}
										/>
									</nav>
								) : null}
							</TabPane>

							<TabPane tabId='2'>
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
									id='divToPDF'
								>
									<thead className='thead-light'>
										<PostingTableHeader headerType={"array"} headerPayload={headerPayload} />
									</thead>

									<tbody>
										<SettlementTable
											summaryType={"flexcube"}
											Error404Msg={"There is no flex-cube entry for this date!"}
											title={"View Flex-Cube Summary"}
											url={"/downstream/logs/"}
											getItemFunc={() => this.fetchFlexcubeSummaryItem}
											summaryPayload={
												this.props.flexcubeLogSummary ? (
													this.props.flexcubeLogSummary.content
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table>
								{this.props.flexcubeLogSummary ? (
									<nav>
										<Pagination2
											activePage={this.state.activePageFx}
											itemsCountPerPage={this.props.flexcubeLogSummary.size}
											totalItemsCount={
												(this.props.flexcubeLogSummary &&
													this.props.flexcubeLogSummary.totalElements) ||
												null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChangeFx}
										/>
									</nav>
								) : null}
							</TabPane>

							<TabPane tabId='3'>
								<Table
									hover
									bordered
									striped
									responsive
									size='sm'
									className='table-outline mb-0 d-sm-table'
									id='divToPDF'
								>
									<thead className='thead-light'>
										<PostingTableHeader headerType={"array"} headerPayload={headerPayload} />
									</thead>

									<tbody>
										<SettlementTable
											summaryType={"pos-acquirers"}
											Error404Msg={"There is no POS Acquirers entry for this date!"}
											title={"View POS Acquirers Summary"}
											url={"/downstream/logs/"}
											getItemFunc={() => this.fetchPOSacquirerSummaryItem}
											summaryPayload={
												this.props.posAcquirerSummary ? (
													this.props.posAcquirerSummary.content
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table>
								{this.props.posAcquirerSummary ? (
									<nav>
										<Pagination2
											activePage={this.state.activePagePOS}
											itemsCountPerPage={this.props.posAcquirerSummary.size}
											totalItemsCount={
												(this.props.posAcquirerSummary &&
													this.props.posAcquirerSummary.totalElements) ||
												null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChangePOS}
										/>
									</nav>
								) : null}

								{/* {this.props.fetchPOSacquirersSummary ? (
									<nav>
										<Pagination2
											activePage={this.state.activePagePOS}
											itemsCountPerPage={this.props.fetchPOSacquirersSummary.size}
											totalItemsCount={
												(this.props.fetchPOSacquirersSummary &&
													this.props.fetchPOSacquirersSummary.totalElements) ||
												null
											}
											pageRangeDisplayed={5}
											onChange={this.handlePageChangePOS}
										/>
									</nav>
								) : null} */}
							</TabPane>
						</TabContent>
					</Col>
				</Row>
			</div>
		);
	}
}

const mapStateToProps = (state) => {
	return {
		postilionLogSummary      : state.fileSets.postilionLogSummary,
		postilionLogSummaryError : state.fileSets.postilionLogSummaryError,
		flexcubeLogSummary       : state.fileSets.flexcubeLogSummary,
		flexcubeLogSummaryItem   : state.fileSets.flexcubeLogSummaryItem,
		posAcquirerSummary       : state.fileSets.posAcquirerSummary,
	};
};

const mapDispatchToProps = (dispatch) => {
	return bindActionCreators(
		{
			fetchpostilionSummary,
			fetchFlexcubeSummary,
			fetchPOSacquirersSummary,
			fetchPostilionSummaryItem,
		},
		dispatch,
	);
};

export default connect(mapStateToProps, mapDispatchToProps)(Summary);
